/**
 * \class FsName
 * \brief Handle UTF-8 file names.
 */
class FsName {
 public:
  /** Beginning of LFN. */
  const char* begin;
  /** Next LFN character of end. */
  const char* next;
  /** Position one beyond last LFN character. */
  const char* end;
# 55 "C:/Users/Miyam/AppData/Local/Arduino15/packages/teensy/hardware/avr/1.62.0/libraries/SdFat/src/common/FsName.h"
  uint16_t ls = 0;
  bool atEnd() {
    return !ls && next == end;
  }
  void reset() {
    next = begin;
    ls = 0; // lowSurrogate
  }
  uint16_t get16();

};
